    'chat.privacy_default.s2_li6': "▸ Dati di utilizzo dell'applicazione NutriPlan (accessi, alimenti registrati, obiettivi)",
    'chat.privacy_default.s3_header': '3. MODALITÀ DI TRATTAMENTO E SICUREZZA',
    'chat.privacy_default.s3_body': 'I dati sono trattati con strumenti elettronici e/o cartacei, con misure di sicurezza tecniche e organizzative adeguate a prevenire accessi non autorizzati, perdita, distruzione o divulgazione non consentita. La piattaforma NutriPlan utilizza connessioni cifrate (TLS/SSL), autenticazione sicura e infrastrutture cloud conformi al GDPR.',
    'chat.privacy_default.s4_header': '4. PERIODO DI CONSERVAZIONE',
    'chat.privacy_default.s4_intro': 'I dati vengono conservati per il periodo strettamente necessario al raggiungimento delle finalità per cui sono stati raccolti, e comunque:',
