    'chat.privacy_default.s5_header': '5. COMUNICAZIONE E CONDIVISIONE DEI DATI',
    'chat.privacy_default.s5_intro': 'I dati personali non vengono diffusi a terzi. Possono essere comunicati esclusivamente a:',
