    'chat.privacy_default.s5_li3': '▸ Fornitori di servizi tecnologici (infrastruttura cloud, applicativi software) vincolati da accordi di riservatezza conformi al GDPR',
    'chat.privacy_default.s5_li4': '▸ Autorità pubbliche, nei casi previsti dalla legge',
    'chat.privacy_default.s6_header': "6. TRASFERIMENTO DATI ALL'ESTERO",
    'chat.privacy_default.s6_body': "I dati potrebbero essere trattati da fornitori di servizi cloud ubicati in Paesi dell'Unione Europea o in Paesi terzi che garantiscono un livello di protezione adeguato ai sensi degli artt. 44-49 GDPR, come gli USA nell'ambito del Data Privacy Framework.",
    'chat.privacy_default.s7_header': "7. DIRITTI DELL'INTERESSATO",
    'chat.privacy_default.s7_intro': 'In qualsiasi momento Lei potrà esercitare i seguenti diritti (artt. 15–22 GDPR), inviando richiesta scritta al Titolare del trattamento:',
    'chat.privacy_default.s7_li1': '▸ Diritto di accesso (art. 15): ottenere conferma che i Suoi dati siano trattati e riceverne copia',
    'chat.privacy_default.s7_li2': '▸ Diritto di rettifica (art. 16): correggere dati inesatti o incompleti',
    'chat.privacy_default.s7_li3': '▸ Diritto alla cancellazione / "diritto all\'oblio" (art. 17): chiedere la cancellazione dei dati quando non più necessari',
    'chat.privacy_default.s7_li4': '▸ Diritto alla limitazione del trattamento (art. 18): ottenere la sospensione temporanea del trattamento',
    'chat.privacy_default.s7_li5': '▸ Diritto alla portabilità dei dati (art. 20): ricevere i Suoi dati in formato strutturato e leggibile da dispositivo automatico',
    'chat.privacy_default.s7_li6': '▸ Diritto di opposizione (art. 21): opporsi al trattamento in qualsiasi momento',
    'chat.privacy_default.s7_li7': '▸ Diritto di revocare il consenso (art. 7, par. 3): la revoca non pregiudica la liceità del trattamento effettuato prima della stessa',
    'chat.privacy_default.s8_header': '8. RECLAMO AL GARANTE',
    'chat.privacy_default.s8_body': 'Lei ha il diritto di proporre reclamo al Garante per la Protezione dei Dati Personali qualora ritenga che il trattamento dei Suoi dati personali sia effettuato in violazione del GDPR.',
    'chat.privacy_default.s8_site': 'Sito ufficiale: www.garanteprivacy.it',
    'chat.privacy_default.s8_address': 'Indirizzo: Piazza Venezia 11, 00187 Roma',
    'chat.privacy_default.s8_email': 'E-mail: garante@gpdp.it',
    'chat.privacy_default.declaration_header': 'DICHIARAZIONE DI CONSENSO',
    'chat.privacy_default.declaration_body': 'Il/La sottoscritto/a dichiara di aver letto integralmente la presente informativa, di averla compresa in ogni sua parte e di prestare il proprio consenso libero, specifico, informato e inequivocabile al trattamento dei propri dati personali, inclusi quelli relativi allo stato di salute, per le finalità sopra indicate.',
    'chat.privacy_default.date_label': 'Data: {{date}}',
