    'subscription.faq_q1': 'Cosa include il piano gratuito?',
    'subscription.faq_a1': 'Il piano gratuito include tutto il necessario per seguire la terapia del tuo dietista: visualizzazione del piano alimentare, chat, documenti, diario degli ultimi 7 giorni, tracciamento acqua e peso.',
    'subscription.faq_q2': 'Posso disdire in qualsiasi momento?',
    'subscription.faq_a2': 'Sì, puoi cancellare l\'abbonamento quando vuoi dal portale Stripe (pulsante "Gestisci abbonamento"). L\'accesso Pro rimane attivo fino alla fine del periodo già pagato. Hai inoltre diritto di recesso entro 14 giorni dalla sottoscrizione ai sensi del Codice del Consumo, indipendentemente dalla cancellazione ordinaria.',
    'subscription.faq_q3': 'I miei dati sono al sicuro?',
    'subscription.faq_a3': 'Sì. I dati sono archiviati su Supabase (PostgreSQL) con crittografia TLS in transito e a riposo. I pagamenti sono gestiti da Stripe, certificato PCI-DSS Level 1. Non conserviamo mai i dati della tua carta.',
    'subscription.faq_q4': 'Il mio dietista vede che sono abbonato?',
    'subscription.faq_a4': "No, il piano che scegli riguarda solo le funzionalità che usi tu sull'app. Il rapporto con il tuo dietista è indipendente dall'abbonamento.",
    'subscription.faq_q5': 'Esiste una prova gratuita?',
    'subscription.faq_a5': 'Sì, il piano Pro include 7 giorni di prova gratuita. Non serve inserire la carta di credito durante la prova.',
