    'specialty.tips.diabete.2': 'Se sei in terapia insulinica, evita di saltare i pasti — aumenta il rischio di ipoglicemia.',
    'specialty.tips.diabete.3': 'Ruota il sito di iniezione dell’insulina per evitare indurimenti della pelle nel tempo.',
    'specialty.tips.obesita.0': 'Una perdita di peso graduale (0,5–1 kg a settimana) è più sostenibile nel tempo di un dimagrimento rapido.',
    'specialty.tips.obesita.1': 'Bere un bicchiere d’acqua prima dei pasti può aiutare il senso di sazietà.',
    'specialty.tips.obesita.2': 'Il segnale di sazietà impiega circa 20 minuti ad arrivare al cervello: mangiare lentamente aiuta a non superarlo.',
    'specialty.tips.obesita.3': 'Dormire meno di 7 ore a notte altera gli ormoni della fame (grelina e leptina).',
    'specialty.tips.sport.0': 'Idratati regolarmente durante l’allenamento, non solo quando avverti la sete.',
    'specialty.tips.sport.1': 'Nei 30–60 minuti dopo l’allenamento il corpo assorbe meglio proteine e carboidrati per il recupero.',
    'specialty.tips.sport.2': 'Non provare mai un alimento o integratore nuovo il giorno di una gara.',
    'specialty.tips.renale.0': 'Bevi secondo le indicazioni del tuo team curante: sia troppo che troppo poco liquido può essere dannoso.',
    'specialty.tips.renale.1': 'La doppia bollitura (lisciviazione) riduce il potassio delle verdure del 30–50%.',
    'specialty.tips.renale.2': 'Leggi le etichette: gli additivi a base di fosforo (sigle E338–E341) si assorbono quasi al 100%, molto più di quello naturale.',
    'specialty.tips.chetogenica.0': 'Nei primi giorni puoi avvertire la "keto flu" (stanchezza, mal di testa) — aumentare sodio, potassio e magnesio spesso aiuta.',
    'specialty.tips.chetogenica.1': 'La chetosi ha un effetto diuretico: bevi a sufficienza.',
    'specialty.tips.chetogenica.2': 'Monitora chetoni e glicemia regolarmente, specialmente nelle prime settimane.',
    'specialty.tips.oncologia.0': 'In caso di nausea, prova pasti piccoli e frequenti invece di 3 pasti abbondanti.',
    'specialty.tips.oncologia.1': 'Se noti alterazioni del gusto, i cibi freddi o a temperatura ambiente sono spesso meglio tollerati di quelli caldi.',
    'specialty.tips.oncologia.2': 'Con la mucosite, prediligi cibi morbidi e non acidi o piccanti.',
    'specialty.tips.pancreas.0': 'Assumi gli enzimi pancreatici SEMPRE all’inizio del pasto, mai a fine pasto.',
    'specialty.tips.pancreas.1': 'Non saltare le vitamine liposolubili (A, D, E, K) se prescritte: il loro assorbimento dipende dai grassi.',
    'specialty.tips.pancreas.2': 'Pasti piccoli e frequenti sono spesso meglio tollerati di pasti abbondanti.',
    'specialty.tips.pediatria.0': 'Offri il cibo senza forzare: i bambini regolano naturalmente l’appetito se non si creano conflitti a tavola.',
    'specialty.tips.pediatria.1': 'I bambini imparano le abitudini alimentari osservando gli adulti attorno a loro.',
    'specialty.tips.pediatria.2': 'Orari dei pasti regolari aiutano la regolazione naturale dell’appetito.',
    'specialty.tips.disfagia.0': 'Mangia seduto/a con la schiena dritta, mai sdraiato/a.',
    'specialty.tips.disfagia.1': 'Fai bocconi piccoli e assicurati di aver deglutito prima del boccone successivo.',
    'specialty.tips.disfagia.2': 'Se usi un addensante, rispetta sempre la quantità indicata dal tuo logopedista/dietista.',
    'specialty.tips.paziente_sano.0': 'Varia gli alimenti nell’arco della settimana per un apporto più completo di nutrienti.',
    'specialty.tips.paziente_sano.1': 'Preferisci alimenti integrali e minimamente processati quando possibile.',
    'specialty.tips.paziente_sano.2': 'Anche un piccolo aumento di attività quotidiana (camminare, fare le scale) fa la differenza nel tempo.',
    'specialty.tips.gravidanza.0': 'Evita alcolici, pesce ad alto contenuto di mercurio, formaggi non pastorizzati e salumi crudi.',
    'specialty.tips.gravidanza.1': 'Assicurati un adeguato apporto di acido folico, ferro e calcio — parlane con il tuo ginecologo per l’eventuale integrazione.',
    'specialty.tips.gravidanza.2': 'In caso di nausea, pasti piccoli e frequenti, evitando di restare a digiuno a lungo, spesso aiutano.',
    'specialty.tips.dca.0': 'Numero Verde SOS Disturbi Alimentari (Ministero della Salute) — gratuito e anonimo',
    'specialty.tips.dca.1': 'Non sei solo/a in questo percorso — il tuo team di cura è qui per te.',
    'specialty.tips.dca.2': 'Se un pensiero ti preoccupa, parlarne con il tuo terapeuta o dietista appena possibile fa la differenza.',
