    'chat.sign': 'Sign',
    'chat.sign_document': 'Sign document',
    'chat.privacy_default.title': 'INFORMED CONSENT FORM FOR THE PROCESSING OF PERSONAL DATA\nunder EU Regulation 2016/679 (GDPR) and Italian Legislative Decree 196/2003 as amended.',
    'chat.privacy_default.controller_header': 'DATA CONTROLLER',
    'chat.privacy_default.controller_body': "The data controller is the Nutrition Professional who activated your account on this platform. Their contact details are shown on the professional's profile within the application.",
    'chat.privacy_default.s1_header': '1. PURPOSES AND LEGAL BASIS OF PROCESSING',
    'chat.privacy_default.s1_intro': 'Personal data, including health data (special categories under Art. 9 GDPR), is processed for the following purposes:',
    'chat.privacy_default.s1_a': "a) Management of the patient's nutrition and clinical record",
    'chat.privacy_default.s1_b': 'b) Preparation and updating of personalized meal plans',
    'chat.privacy_default.s1_c': 'c) Monitoring of nutritional progress, body weight and overall wellbeing',
    'chat.privacy_default.s1_d': 'd) Communications relating to appointments and the therapeutic-nutritional path',
    'chat.privacy_default.s1_e': 'e) Storage of clinical documents, reports and prescriptions',
    'chat.privacy_default.s1_f': 'f) Compliance with healthcare and professional legal obligations',
    'chat.privacy_default.s1_basis_intro': 'The legal basis for processing is:',
    'chat.privacy_default.s1_basis_a': "- The data subject's explicit consent (Art. 6.1.a and Art. 9.2.a GDPR)",
    'chat.privacy_default.s1_basis_b': '- Performance of the professional service contract (Art. 6.1.b GDPR)',
    'chat.privacy_default.s1_basis_c': '- Compliance with legal obligations (Art. 6.1.c GDPR)',
    'chat.privacy_default.s2_header': '2. CATEGORIES OF DATA PROCESSED',
    'chat.privacy_default.s2_intro': 'The following personal data is processed:',
    'chat.privacy_default.s2_li1': '▸ Identification and contact data: first name, last name, date of birth, tax ID, address, phone number, email address',
    'chat.privacy_default.s2_li2': '▸ Anthropometric data: current and historical weight, height, body mass index (BMI), body composition',
    'chat.privacy_default.s2_li3': '▸ Health data: diagnosed conditions, medications taken, food intolerances and allergies, blood tests and reports voluntarily provided, dietary history',
    'chat.privacy_default.s2_li4': '▸ Lifestyle data: physical activity, eating habits, dietary preferences and restrictions',
    'chat.privacy_default.s2_li5': '▸ Body photographs, if expressly agreed with the professional',
    'chat.privacy_default.s2_li6': '▸ NutriPlan app usage data (logins, logged foods, goals)',
    'chat.privacy_default.s3_header': '3. PROCESSING METHODS AND SECURITY',
    'chat.privacy_default.s3_body': 'Data is processed using electronic and/or paper-based tools, with technical and organizational security measures adequate to prevent unauthorized access, loss, destruction or unauthorized disclosure. The NutriPlan platform uses encrypted connections (TLS/SSL), secure authentication and GDPR-compliant cloud infrastructure.',
    'chat.privacy_default.s4_header': '4. RETENTION PERIOD',
    'chat.privacy_default.s4_intro': 'Data is retained for the period strictly necessary to achieve the purposes for which it was collected, and in any case:',
    'chat.privacy_default.s4_li1': '- For the entire duration of the professional relationship',
    'chat.privacy_default.s4_li2': '- For a maximum of 10 years from the end of the relationship, unless legal obligations require longer retention',
    'chat.privacy_default.s4_li3': '- For the entire duration required by applicable tax and accounting regulations',
    'chat.privacy_default.s5_header': '5. DISCLOSURE AND SHARING OF DATA',
    'chat.privacy_default.s5_intro': 'Personal data is not disclosed to third parties. It may only be communicated to:',
    'chat.privacy_default.s5_li1': '▸ Treating physicians and other healthcare specialists, subject to the data subject\'s explicit consent',
    'chat.privacy_default.s5_li2': '▸ Administrative staff of the practice, strictly within what is necessary',
    'chat.privacy_default.s5_li3': '▸ Technology service providers (cloud infrastructure, software applications) bound by GDPR-compliant confidentiality agreements',
    'chat.privacy_default.s5_li4': '▸ Public authorities, in the cases provided for by law',
    'chat.privacy_default.s6_header': '6. INTERNATIONAL DATA TRANSFERS',
    'chat.privacy_default.s6_body': 'Data may be processed by cloud service providers located in European Union countries or in third countries that guarantee an adequate level of protection under Articles 44-49 GDPR, such as the USA under the Data Privacy Framework.',
    'chat.privacy_default.s7_header': '7. DATA SUBJECT RIGHTS',
    'chat.privacy_default.s7_intro': 'You may exercise the following rights at any time (Articles 15–22 GDPR) by sending a written request to the Data Controller:',
    'chat.privacy_default.s7_li1': '▸ Right of access (Art. 15): obtain confirmation that your data is being processed and receive a copy of it',
    'chat.privacy_default.s7_li2': '▸ Right to rectification (Art. 16): correct inaccurate or incomplete data',
    'chat.privacy_default.s7_li3': '▸ Right to erasure / "right to be forgotten" (Art. 17): request deletion of data when no longer necessary',
    'chat.privacy_default.s7_li4': '▸ Right to restriction of processing (Art. 18): obtain temporary suspension of processing',
    'chat.privacy_default.s7_li5': '▸ Right to data portability (Art. 20): receive your data in a structured, machine-readable format',
    'chat.privacy_default.s7_li6': '▸ Right to object (Art. 21): object to processing at any time',
    'chat.privacy_default.s7_li7': '▸ Right to withdraw consent (Art. 7.3): withdrawal does not affect the lawfulness of processing carried out before it',
    'chat.privacy_default.s8_header': '8. COMPLAINT TO THE SUPERVISORY AUTHORITY',
    'chat.privacy_default.s8_body': 'You have the right to lodge a complaint with the Italian Data Protection Authority (Garante per la Protezione dei Dati Personali) if you believe that the processing of your personal data violates the GDPR.',
    'chat.privacy_default.s8_site': 'Official website: www.garanteprivacy.it',
    'chat.privacy_default.s8_address': 'Address: Piazza Venezia 11, 00187 Rome, Italy',
    'chat.privacy_default.s8_email': 'Email: garante@gpdp.it',
    'chat.privacy_default.declaration_header': 'CONSENT DECLARATION',
    'chat.privacy_default.declaration_body': 'The undersigned declares to have read this notice in full, to have understood it in every part, and to freely, specifically, knowingly and unambiguously give consent to the processing of their personal data, including health-related data, for the purposes indicated above.',
    'chat.privacy_default.date_label': 'Date: {{date}}',
