    'specialty.tips.diabete.0': 'Always carry a source of fast-acting sugar (e.g. fruit juice or sugar cubes) to manage a possible episode of hypoglycemia.',
    'specialty.tips.diabete.1': 'Check your blood glucose before and after physical activity: exercise can lower it for several hours afterward.',
    'specialty.tips.diabete.2': 'If you\'re on insulin therapy, avoid skipping meals — it increases the risk of hypoglycemia.',
    'specialty.tips.diabete.3': 'Rotate your insulin injection site to prevent skin thickening (lipohypertrophy) over time.',
    'specialty.tips.obesita.0': 'Gradual weight loss (0.5–1 kg per week) is more sustainable over time than rapid weight loss.',
    'specialty.tips.obesita.1': 'Drinking a glass of water before meals can help you feel fuller.',
    'specialty.tips.obesita.2': 'It takes about 20 minutes for the fullness signal to reach your brain: eating slowly helps you avoid overeating.',
    'specialty.tips.obesita.3': 'Sleeping less than 7 hours a night disrupts hunger hormones (ghrelin and leptin).',
    'specialty.tips.sport.0': 'Hydrate regularly during training, not just when you feel thirsty.',
    'specialty.tips.sport.1': 'In the 30–60 minutes after training, your body absorbs protein and carbohydrates better for recovery.',
    'specialty.tips.sport.2': 'Never try a new food or supplement on race/competition day.',
    'specialty.tips.renale.0': 'Drink according to your care team\'s guidance: both too much and too little fluid can be harmful.',
    'specialty.tips.renale.1': 'Double-boiling (leaching) reduces the potassium content of vegetables by 30–50%.',
    'specialty.tips.renale.2': 'Read food labels: phosphorus-based additives (codes E338–E341) are absorbed at nearly 100%, far more than naturally occurring phosphorus.',
    'specialty.tips.chetogenica.0': 'In the first few days you may experience the "keto flu" (fatigue, headache) — increasing sodium, potassium, and magnesium often helps.',
    'specialty.tips.chetogenica.1': 'Ketosis has a diuretic effect: make sure to drink enough fluids.',
    'specialty.tips.chetogenica.2': 'Monitor ketones and blood glucose regularly, especially in the first few weeks.',
    'specialty.tips.oncologia.0': 'If you feel nauseous, try small, frequent meals instead of 3 large ones.',
    'specialty.tips.oncologia.1': 'If you notice changes in taste, cold or room-temperature foods are often better tolerated than hot ones.',
    'specialty.tips.oncologia.2': 'If you have mucositis, choose soft foods that are not acidic or spicy.',
    'specialty.tips.pancreas.0': 'Always take pancreatic enzymes at the START of the meal, never at the end.',
    'specialty.tips.pancreas.1': 'Do not skip fat-soluble vitamins (A, D, E, K) if prescribed: their absorption depends on dietary fat.',
    'specialty.tips.pancreas.2': 'Small, frequent meals are often better tolerated than large ones.',
    'specialty.tips.pediatria.0': 'Offer food without forcing it: children naturally regulate their appetite when mealtimes aren\'t a source of conflict.',
    'specialty.tips.pediatria.1': 'Children learn eating habits by watching the adults around them.',
    'specialty.tips.pediatria.2': 'Regular mealtimes support children\'s natural appetite regulation.',
    'specialty.tips.disfagia.0': 'Eat sitting upright with a straight back, never lying down.',
    'specialty.tips.disfagia.1': 'Take small bites and make sure you have swallowed before taking the next one.',
    'specialty.tips.disfagia.2': 'If you use a thickener, always follow the amount indicated by your speech therapist/dietitian.',
    'specialty.tips.paziente_sano.0': 'Vary your foods throughout the week for a more complete nutrient intake.',
    'specialty.tips.paziente_sano.1': 'Choose whole, minimally processed foods whenever possible.',
    'specialty.tips.paziente_sano.2': 'Even a small increase in daily activity (walking, taking the stairs) makes a difference over time.',
    'specialty.tips.gravidanza.0': 'Avoid alcohol, high-mercury fish, unpasteurized cheeses, and cured raw meats.',
    'specialty.tips.gravidanza.1': 'Make sure you get enough folic acid, iron, and calcium — talk to your gynecologist about possible supplementation.',
    'specialty.tips.gravidanza.2': 'If you feel nauseous, small and frequent meals — avoiding long periods without eating — often help.',
    'specialty.tips.dca.0': 'Eating Disorders Toll-Free Helpline (Italian Ministry of Health) — free and anonymous',
    'specialty.tips.dca.1': 'You are not alone on this journey — your care team is here for you.',
    'specialty.tips.dca.2': 'If a thought is worrying you, talking to your therapist or dietitian as soon as possible makes a difference.',
